{"command":"python3 -c '
import workcell

while True:
    r = workcell.call("arm", "step", "-2.0")
    print(r.text)
    # Parse Fz or read ft
    ft = workcell.call("ft", "read")
    print("ft:", ft.text)
    # Check if Fz > 0.2
    # r.data might have z and fz?
    print("data:", r.data)
    fz = None
    if r.data and "fz" in r.data:
        fz = r.data["fz"]
    if fz is not None and fz > 0.2:
        print("Contact detected!")
        break
    if not r.data:
        # parse from text
        # tip z=... Fz=...
        parts = r.text.split()
        for p in parts:
            if p.startswith("Fz="):
                fz = float(p.replace("Fz=", "").replace("N", ""))
                if fz > 0.2:
                    break
        if fz is not None and fz > 0.2:
            print("Contact detected from text!")
            break
'"}

